<?php
$pageTitle='حساب‌های ایمیل'; $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['id']??0);$email=trim($_POST['email_address']??'');$name=trim($_POST['display_name']??'');$pass=$_POST['password']??'';$ih=trim($_POST['imap_host']??'');$ip=(int)($_POST['imap_port']??993);$ie=$_POST['imap_encryption']??'ssl';$sh=trim($_POST['smtp_host']??'');$sp=(int)($_POST['smtp_port']??587);$se=$_POST['smtp_encryption']??'tls';
 if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$name===''||$ih===''||$sh===''||$ip<1||$sp<1||($id===0&&$pass==='')){$error='اطلاعات حساب کامل یا معتبر نیست.';}else{if($id){$a=MailboxService::account($id);if(!$a)$error='حساب پیدا نشد.';else{if($pass!==''){ $q=db()->prepare("UPDATE email_accounts SET email_address=?,display_name=?,imap_host=?,imap_port=?,imap_encryption=?,smtp_host=?,smtp_port=?,smtp_encryption=?,password_encrypted=? WHERE id=?");$q->execute([$email,$name,$ih,$ip,$ie,$sh,$sp,$se,encryptMailboxSecret($pass),$id]);}else{$q=db()->prepare("UPDATE email_accounts SET email_address=?,display_name=?,imap_host=?,imap_port=?,imap_encryption=?,smtp_host=?,smtp_port=?,smtp_encryption=? WHERE id=?");$q->execute([$email,$name,$ih,$ip,$ie,$sh,$sp,$se,$id]);} header('Location:/admin/email_accounts.php?saved=1');exit;}}else{$q=db()->prepare("INSERT INTO email_accounts(email_address,display_name,imap_host,imap_port,imap_encryption,smtp_host,smtp_port,smtp_encryption,password_encrypted) VALUES(?,?,?,?,?,?,?,?,?)");$q->execute([$email,$name,$ih,$ip,$ie,$sh,$sp,$se,encryptMailboxSecret($pass)]);header('Location:/admin/email_accounts.php?saved=1');exit;}}}
$accounts=db()->query('SELECT id,email_address,display_name,imap_host,imap_port,imap_encryption,smtp_host,smtp_port,smtp_encryption FROM email_accounts ORDER BY id')->fetchAll(); $editId=(int)($_GET['edit']??0);$edit=$editId?MailboxService::account($editId):null; renderView('admin/email_accounts',compact('pageTitle','accounts','edit','error'));
